WF.undo=function(){"use strict";const STORAGE_KEY="wf_checklist_undo_stack",MAX_ENTRIES=10,UNDO_EVENT="wf:undo-changed";function sanitizeStack(raw){if(!Array.isArray(raw))return[];const clean=[];for(const entry of raw){if(!entry||!Number.isSafeInteger(entry.index)||!Array.isArray(entry.changes))continue;const changes=entry.changes.filter((c=>c&&"string"==typeof c.uniqueName&&c.uniqueName.length>0&&"boolean"==typeof c.previous)).map((c=>({uniqueName:c.uniqueName,previous:c.previous})));changes.length>0&&clean.push({index:entry.index,changes:changes})}return clean.sort(((a,b)=>a.index-b.index)),clean.slice(-MAX_ENTRIES)}let stack=function(){try{const raw=localStorage.getItem(STORAGE_KEY);return raw?sanitizeStack(JSON.parse(raw)):[]}catch(err){return WF.logs.AddLog("Undo stack could not be loaded, starting empty","error",err),[]}}();function notify(){window.dispatchEvent(new CustomEvent(UNDO_EVENT))}function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(stack))}catch(err){WF.logs.AddLog("Undo stack could not be saved","error",err)}notify()}return window.addEventListener("storage",(event=>{if(null===event.key||event.key===STORAGE_KEY){try{stack=null===event.key||null===event.newValue?[]:sanitizeStack(JSON.parse(event.newValue))}catch(err){WF.logs.AddLog("Undo stack from another tab is unreadable, reset","error",err),stack=[]}notify()}})),{record:function(uniqueNames,newState){try{if(!Array.isArray(uniqueNames)||"boolean"!=typeof newState)return!1;const progress=WF.storage.load()||{},seen=new Set,changes=[];for(const name of uniqueNames){if("string"!=typeof name||0===name.length||seen.has(name))continue;seen.add(name);const previous=!!progress[name];previous!==newState&&changes.push({uniqueName:name,previous:previous})}if(0===changes.length)return!1;const index=stack.length>0?stack[stack.length-1].index+1:1;for(stack.push({index:index,changes:changes});stack.length>MAX_ENTRIES;)stack.shift();return persist(),!0}catch(err){return WF.logs.AddLog("Undo record failed","error",err),!1}},undoLast:function(){const entry=stack[stack.length-1];if(!entry)return 0;const validNames=new Set(WF.data.map((item=>item.item_name))),next={...WF.storage.load()};let restored=0;for(const{uniqueName:uniqueName,previous:previous}of entry.changes)validNames.has(uniqueName)&&(next[uniqueName]=previous,restored++);return restored>0&&WF.storage.save(next),stack.pop(),persist(),restored},clear:function(){stack=[];try{localStorage.removeItem(STORAGE_KEY)}catch(err){WF.logs.AddLog("Undo stack could not be cleared","error",err)}notify()},size:()=>stack.length,peek:function(){const entry=stack[stack.length-1];return entry?{count:entry.changes.length,restoreTo:entry.changes[0].previous,uniqueNames:entry.changes.map((change=>change.uniqueName))}:null}}}();